<?php
require_once __DIR__.'/../includes/auth.php';$admin=require_role('admin');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$uid=(int)($_POST['user_id']??0);$status=$_POST['status']??'';if(in_array($status,['pending','verified','rejected'],true)){$q=db()->prepare("UPDATE provider_profiles SET verification_status=?,verified_at=".($status==='verified'?"NOW()":"NULL")." WHERE user_id=?");$q->execute([$status,$uid]);log_activity((int)$admin['id'],'verification_'.$status,'provider',$uid);flash('success','Verification status updated.');}redirect('admin/providers.php');}
$pg=pagination_window(30,60);$q=db()->prepare("SELECT u.id,u.name,u.email,u.status,p.verification_status,p.created_at FROM provider_profiles p JOIN users u ON u.id=p.user_id WHERE u.role='provider' ORDER BY p.id DESC LIMIT ".($pg['per']+1)." OFFSET ".$pg['offset']);$q->execute();$rows=$q->fetchAll();$hasNext=trim_page_results($rows,$pg['per']);$success=flash('success');release_session_lock();$pageTitle='Manage Providers — LocalConnect';require __DIR__.'/../includes/header.php';?>
<div class="container py-4"><?php include __DIR__.'/_nav.php';?><h1>Manage providers</h1><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><div class="table-responsive card border-0 shadow-sm"><table class="table mb-0"><tr><th>Name</th><th>Account</th><th>Verification</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?><div class="small text-muted"><?=e($r['email'])?></div></td><td><?=e($r['status'])?></td><td><?=e($r['verification_status'])?></td><td><form method="post" class="d-flex gap-1"><?=csrf_field()?><input type="hidden" name="user_id" value="<?=$r['id']?>"><button name="status" value="verified" class="btn btn-sm btn-success">Verify</button><button name="status" value="rejected" class="btn btn-sm btn-outline-danger">Reject</button><button name="status" value="pending" class="btn btn-sm btn-outline-secondary">Pending</button></form></td></tr><?php endforeach;?></table></div><?=pagination_nav($pg['page'],$hasNext)?></div><?php require __DIR__.'/../includes/footer.php';?>
